/* From Uiverse.io by alexruix - Tags: white, card, hover, clean */
.__UIV_SCOPE__ .container {
  position: relative;
  width: 190px;
  height: 254px;
}

.__UIV_SCOPE__ .card {
  position: relative;
  width: 190px;
  height: 254px;
  background: #f5f5f5;
  border-radius: 8px;
  color: #232323;
  padding: 16px;
  border: 1px solid #232323;
  transition: all .5s ease-in-out;
  overflow: hidden;
}

.__UIV_SCOPE__ .card-hidden {
  display: flex;
  transform: translateY(200%);
  flex-direction: column;
  gap: .5rem;
  transition: transform .5s ease-in, opacity .3s ease-in;
  opacity: 0;
}

.__UIV_SCOPE__ .card-border {
  position: absolute;
  width: 100%;
  height: 100%;
  left: 0;
  top: 0;
  border: 1px dashed #232323;
  border-radius: 8px;
  z-index: -1;
}

/*Hovers*/
.__UIV_SCOPE__ .card:hover {
  transform: translate(-15px, -15px);
  border-color: #5bc0eb;
}

.__UIV_SCOPE__ .card:hover .card-hidden {
  transform: translateY(0);
  opacity: 1;
}

.__UIV_SCOPE__ .card:hover .title {
  transform: translateY(200%);
}

/*Text*/
.__UIV_SCOPE__ .title {
  position: absolute;
  bottom: 1rem;
  font-weight: 700;
  font-size: 1.5rem;
  transition: transform .25s ease-out;
}

.__UIV_SCOPE__ .title-in {
  font-weight: 700;
  font-size: 1.25rem;
}

/*Button*/
.__UIV_SCOPE__ .button {
  display: inline-flex;
  justify-content: center;
  padding: 8px;
  border-radius: 24px;
  font-weight: 600;
  background-color: #5bc0eb;
  cursor: pointer;
  transition: background-color .3s ease-in-out;
}

.__UIV_SCOPE__ .button:hover {
  background-color: #53aed4;
}
